function setupRatio () {
	let originalRatio = 800 / 900;
	let canvasRatio = windowWidth / windowHeight;

	if(random() < 0.5) // landscape
	{
		originalRatio = 800 / 900 ;
	}

	if(canvasRatio > originalRatio)
	{
		canvasH = windowHeight;
		canvasW = windowHeight * originalRatio;
	}
	else
	{
		canvasW = windowWidth;
		canvasH = windowWidth / originalRatio;
	}
}

