function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function getTypeRects(typeIndex) {
  var xCount = 0;
  var yCount = 0;

  if (typeIndex == 0) {
    xCount = 1;
    yCount = int(random(1, 24));
  }
  else if (typeIndex == 1) {
    xCount = int(random(1, 24));
    yCount = 1;
  }
  else if (typeIndex == 2) {
    xCount = int(random(12, 24));
    yCount = int(random(12, 24));
  }
  else if(typeIndex == 3){
    xCount = int(random(1, 24));
    yCount = int(random(1, 24));
  }
	else if (typeIndex == 4) {
    xCount = int(random(1, 6));
    yCount = int(random(1, 6));
  }

  return [xCount, yCount];
}


function NYLerpColor(_colorA, _colorB, _t) {
  var hueA = hue(_colorA);
  var hueB = hue(_colorB);

  let hueDiff = abs(hueB - hueA);

  if (abs((hueB - 360) - hueA) < hueDiff) {
    hueB -= 360;
  }
  else if (abs((hueB + 360) - hueA) < hueDiff) {
    hueB += 360;
  }
  else {
    return lerpColor(_colorA, _colorB, _t);
  }

  var satA = saturation(_colorA);
  var briA = brightness(_colorA);
  let alphaA = alpha(_colorA);

  var satB = saturation(_colorB);
  var briB = brightness(_colorB);
  let alphaB = alpha(_colorB);

  let resultHue = lerp(hueA, hueB, _t);
  let resultSat = lerp(satA, satB, _t);
  let resultBri = lerp(briA, briB, _t);
  let resultAlpha = lerp(alphaA, alphaB, _t);

  if (resultHue < 0) {
    resultHue += 360;
  }
  else if (resultHue > 360) {
    resultHue -= 360;
  }

  return color(resultHue, resultSat, resultBri, resultAlpha);
}

function processHue(_hue) {
  let result = _hue % 360;
  if (result < 0) {
    result += 360;
  }
  return result;
}

function keyPressed(e) {
  if (e.key == 's' || e.key == 'S') {
    save('texture.png');
  }
}

